<?php
declare(strict_types=1);
return [
"CREATE TABLE svc_operations (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,service_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,order_item_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,kind VARCHAR(24) CHARACTER SET ascii NOT NULL,generation INT UNSIGNED NOT NULL,request_fingerprint CHAR(64) CHARACTER SET ascii NOT NULL,status VARCHAR(24) CHARACTER SET ascii NOT NULL DEFAULT 'PENDING',lease_token CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,lease_until DATETIME(6) NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_svc_claim(order_item_id,kind,generation),KEY ix_svc_pending(status,created_at,id),KEY ix_svc_expiry(status,lease_until,id),FOREIGN KEY(service_id) REFERENCES svc_services(id),CHECK(kind IN ('CREATE')),CHECK(status IN ('PENDING','RUNNING','SUCCEEDED','FAILED','UNKNOWN'))) ENGINE=InnoDB",
"CREATE TABLE svc_provider_operations (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,lifecycle_operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,provider VARCHAR(24) CHARACTER SET ascii NOT NULL DEFAULT 'cpanel',server_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,request_encrypted LONGTEXT NOT NULL,request_fingerprint CHAR(64) CHARACTER SET ascii NOT NULL,status VARCHAR(24) CHARACTER SET ascii NOT NULL DEFAULT 'PENDING',created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(lifecycle_operation_id) REFERENCES svc_operations(id),CHECK(status IN ('PENDING','RUNNING','SUCCEEDED','FAILED','UNKNOWN'))) ENGINE=InnoDB",
"CREATE TABLE svc_attempt_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,lease_token CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,kind VARCHAR(24) CHARACTER SET ascii NOT NULL,safe_code VARCHAR(64) CHARACTER SET ascii NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_svc_attempt_event(operation_id,lease_token,kind),FOREIGN KEY(operation_id) REFERENCES svc_operations(id)) ENGINE=InnoDB",
"CREATE TRIGGER svc_attempt_update BEFORE UPDATE ON svc_attempt_events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable service attempt'",
"CREATE TRIGGER svc_attempt_delete BEFORE DELETE ON svc_attempt_events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable service attempt'",
"CREATE TRIGGER svc_operation_binding BEFORE UPDATE ON svc_operations FOR EACH ROW BEGIN IF OLD.service_id<>NEW.service_id OR OLD.order_item_id<>NEW.order_item_id OR OLD.kind<>NEW.kind OR OLD.generation<>NEW.generation OR OLD.request_fingerprint<>NEW.request_fingerprint OR (OLD.status IN ('SUCCEEDED','FAILED','UNKNOWN') AND NEW.status<>OLD.status) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable service operation binding'; END IF; END",
];
